(7472033, 1186703, 177030, '<td valign="top">Effective use of the fish-eye and wonderful night time exposure.  This one grabbed me from the thumbnail.  Thanks for something different.  10 from me.</td>', 'Effective use of the fish-eye and wonderful night time exposure.  This one grabbed me from the thumbnail.  Thanks for something different.  10 from me.', '2016-09-05 10:34:50.000000', NULL, 1),
(7472034, 1186754, 177030, '<td valign="top">Makes me dizzy just looking at it.  Wish the exposure had allowed better detail and less washout in the top row of windows.</td>', 'Makes me dizzy just looking at it.  Wish the exposure had allowed better detail and less washout in the top row of windows.', '2016-09-05 10:38:11.000000', NULL, 1),
